package com.ray.service.impl;
import com.ray.service.*;import com.ray.vo.AdminEventTicketVO;import java.time.LocalDateTime;import java.util.UUID;import java.util.concurrent.TimeUnit;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Service;
@Service public class EventTicketServiceImpl implements EventTicketService {private final AdminAuthService auth;private final StringRedisTemplate redis;public EventTicketServiceImpl(AdminAuthService auth,StringRedisTemplate redis){this.auth=auth;this.redis=redis;}public AdminEventTicketVO issue(){auth.currentAdmin();String t=UUID.randomUUID().toString().replace("-","");redis.opsForValue().set("roamly:event:ticket:"+t,"1",30,TimeUnit.SECONDS);return new AdminEventTicketVO(t,LocalDateTime.now().plusSeconds(30));}public boolean valid(String t){return t!=null&&Boolean.TRUE.equals(redis.hasKey("roamly:event:ticket:"+t));}}
